export function getNavigationItemsForRole(role: Role): NavItem[] {
  return role === "admin"
    ? adminItems
    : role === "teacher"
      ? teacherItems
      : role === "parent"
        ? parentItems
        : studentItems;
}

interface AppSidebarProps {
  role: Role;
}

export function AppSidebar({ role }: AppSidebarProps) {
  const pathname = useRouterState({ select: (s) => s.location.pathname });
  const items = getNavigationItemsForRole(role);
  const isActive = (url: string) => {
    if (
      url === "/admin" ||
      url === "/teacher" ||
      url === "/parent" ||
      url === "/student"
    )
      return pathname === url;
    return pathname.startsWith(url);
  };
  return (
    <Sidebar
      side="right"
      collapsible="icon"
      className="border-l border-sidebar-border"
    >
      <SidebarHeader className="bg-arabesque border-b border-sidebar-border/60">
        <div className="group-data-[collapsible=icon]:hidden flex flex-col items-center py-4 px-2">
          <img
            src={LOGO_SRC}
            alt="لوگوی دارالقرآن"
            className="w-24 h-24 object-contain drop-shadow-md"
          />
          <span className="mt-2 font-display text-sm font-bold text-sidebar-foreground text-center leading-tight">
            دارالقرآن تخصصی بِرّ الوالدین
          </span>
          <span className="text-[10px] text-sidebar-foreground/60 text-center mt-0.5">
            مرکز تخصصی قرآن کریم
          </span>
        </div>
        <div className="hidden group-data-[collapsible=icon]:flex justify-center py-2">
          <img
            src={LOGO_SRC}
            alt="لوگوی دارالقرآن"
            className="w-8 h-8 object-contain"
          />
        </div>
      </SidebarHeader>
      <SidebarContent className="bg-arabesque">
        <SidebarGroup>
          <SidebarGroupLabel className="text-sidebar-foreground/60 text-xs">
            {role === "admin"
              ? "پنل مدیر"
              : role === "teacher"
                ? "پنل استاد"
                : role === "parent"
                  ? "پنل والدین"
                  : "پنل قرآن‌آموز"}
          </SidebarGroupLabel>
          <SidebarGroupContent>
            <SidebarMenu>
              {items.map((item) => (
                <SidebarMenuItem key={item.url}>
                  <SidebarMenuButton
                    asChild
                    isActive={isActive(item.url)}
                    className="data-[active=true]:bg-sidebar-primary data-[active=true]:text-sidebar-primary-foreground data-[active=true]:font-semibold text-sidebar-foreground hover:bg-sidebar-accent"
                  >
                    <Link to={item.url} className="flex items-center gap-3">
                      <item.icon className="h-4 w-4" />
                      <span>{item.title}</span>
                    </Link>
                  </SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </SidebarGroup>
      </SidebarContent>
    </Sidebar>
  );
}
